import { useEffect, useMemo, useState } from "react";
import {
  Activity, ArrowDownLeft, ArrowRight, ArrowUpRight, Bell, BriefcaseBusiness,
  CalendarDays, Check, CheckCircle2, ChevronDown, CircleHelp, Clock3, CreditCard, FileText,
  Filter, Hammer, Home, IndianRupee, MapPin, Menu, MessageCircle, Search, ClipboardList,
  Settings2, ShieldCheck, Sparkles, Wallet, Wrench, X, Zap
} from "lucide-react";

function readPreviewState(key, fallback) {
  try { const saved = window.localStorage.getItem(`findvia-provider:${key}`); return saved === null ? fallback : JSON.parse(saved); } catch { return fallback; }
}

const jobsSeed = [
  { id: "FV-2048", title: "Kitchen sink tap repair", category: "Plumbing", area: "Vaishali Nagar, Jaipur", distance: "2.4 km away", date: "Today, 4:00 PM", budget: "₹600–₹900", icon: Wrench, tint: "mint", detail: "The kitchen tap is leaking near the base. Please bring standard washers and tools.", customer: "Customer details appear after selection." },
  { id: "FV-2047", title: "Ceiling fan installation", category: "Electrical", area: "Mansarovar, Jaipur", distance: "4.1 km away", date: "Today, 5:30 PM", budget: "₹400–₹700", icon: Zap, tint: "amber", detail: "Install one ceiling fan in a bedroom. Existing wiring is available.", customer: "Customer details appear after selection." },
  { id: "FV-2044", title: "Bathroom door adjustment", category: "Carpentry", area: "Jagatpura, Jaipur", distance: "6.8 km away", date: "Tomorrow, 10:00 AM", budget: "₹500–₹800", icon: Hammer, tint: "violet", detail: "The bathroom door is scraping the floor and needs adjustment.", customer: "Customer details appear after selection." }
];

const navItems = [
  { id: "home", label: "Home", icon: Home },
  { id: "jobs", label: "Jobs", icon: BriefcaseBusiness },
  { id: "work", label: "My Work", icon: ClipboardList },
  { id: "wallet", label: "Wallet", icon: Wallet },
  { id: "profile", label: "Profile", icon: Settings2 }
];

function IconButton({ label, children, onClick, className = "" }) {
  return <button className={`icon-button ${className}`} type="button" aria-label={label} onClick={onClick}>{children}</button>;
}

function StatusPill({ children, tone = "neutral" }) {
  return <span className={`status-pill ${tone}`}>{children}</span>;
}

function JobCard({ job, onOpen, onOffer, language }) {
  const Icon = job.icon;
  const hi = language === "Hindi";
  return (
    <article className="job-card">
      <div className="job-card-top">
        <div className={`category-icon ${job.tint}`}><Icon size={21} strokeWidth={1.9} /></div>
        <div className="job-main">
          <div className="job-title-row"><h3>{job.title}</h3><span className="job-id">{job.id}</span></div>
          <p className="job-category">{job.category}</p>
        </div>
        <span className="distance"><MapPin size={13} />{job.distance}</span>
      </div>
      <div className="job-meta">
        <span><MapPin size={15} />{job.area}</span>
        <span><CalendarDays size={15} />{job.date}</span>
      </div>
      <div className="job-card-bottom">
        <div><span className="eyebrow">{hi ? "आपका ऑफ़र" : "YOUR OFFER"}</span><strong className="job-budget">{hi ? "अपनी कीमत तय करें" : "Set your price"}</strong></div>
        <div className="job-actions"><button className="button button-secondary" onClick={() => onOpen(job)}>{hi ? "विवरण" : "Details"}</button><button className="button button-primary" onClick={() => onOffer(job)}>{hi ? "ऑफ़र भेजें" : "Send offer"} <ArrowRight size={15} /></button></div>
      </div>
    </article>
  );
}

function App() {
  const [page, setPage] = useState("home");
  const [mobileMenu, setMobileMenu] = useState(false);
  const [query, setQuery] = useState("");
  const [filterOpen, setFilterOpen] = useState(false);
  const [categoryFilter, setCategoryFilter] = useState("All categories");
  const [jobTab, setJobTab] = useState("Available");
  const [selectedJob, setSelectedJob] = useState(null);
  const [offerJob, setOfferJob] = useState(null);
  const [offerPrice, setOfferPrice] = useState("");
  const [offerNote, setOfferNote] = useState("");
  const [toast, setToast] = useState("");
  const [showRecharge, setShowRecharge] = useState(false);
  const [rechargeAmount, setRechargeAmount] = useState("500");
  const [rechargeUtr, setRechargeUtr] = useState("");
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [profileName, setProfileName] = useState(() => readPreviewState("profileName", "Rahul Sharma"));
  const [profileService, setProfileService] = useState(() => readPreviewState("profileService", "Plumbing"));
  const [profileSkills, setProfileSkills] = useState(() => readPreviewState("profileSkills", ["Plumbing"]));
  const [serviceAreas, setServiceAreas] = useState(() => readPreviewState("serviceAreas", ["Vaishali Nagar"]));
  const [language, setLanguage] = useState(() => readPreviewState("language", "English"));
  const isHindi = language === "Hindi";
  const [submittedOffers, setSubmittedOffers] = useState(() => readPreviewState("submittedOffers", []));
  const [walletRequests, setWalletRequests] = useState(() => readPreviewState("walletRequests", []));
  const [providerAvailable, setProviderAvailable] = useState(() => readPreviewState("providerAvailable", true));
  useEffect(() => { try { window.localStorage.setItem("findvia-provider:profileName", JSON.stringify(profileName)); } catch {} }, [profileName]);
  useEffect(() => { try { window.localStorage.setItem("findvia-provider:profileService", JSON.stringify(profileService)); } catch {} }, [profileService]);
  useEffect(() => { try { window.localStorage.setItem("findvia-provider:profileSkills", JSON.stringify(profileSkills)); } catch {} }, [profileSkills]);
  useEffect(() => { try { window.localStorage.setItem("findvia-provider:serviceAreas", JSON.stringify(serviceAreas)); } catch {} }, [serviceAreas]);
  useEffect(() => { try { window.localStorage.setItem("findvia-provider:language", JSON.stringify(language)); } catch {} }, [language]);
  useEffect(() => { try { window.localStorage.setItem("findvia-provider:submittedOffers", JSON.stringify(submittedOffers)); } catch {} }, [submittedOffers]);
  useEffect(() => { try { window.localStorage.setItem("findvia-provider:walletRequests", JSON.stringify(walletRequests)); } catch {} }, [walletRequests]);
  useEffect(() => { try { window.localStorage.setItem("findvia-provider:providerAvailable", JSON.stringify(providerAvailable)); } catch {} }, [providerAvailable]);

  const filteredJobs = useMemo(() => jobsSeed.filter(job => {
    const text = `${job.title} ${job.category} ${job.area}`.toLowerCase();
    return text.includes(query.toLowerCase()) && (categoryFilter === "All categories" || job.category === categoryFilter) && (jobTab === "Available" || (jobTab === "My offers" && submittedOffers.some(offer => offer.jobId === job.id)));
  }), [query, categoryFilter, jobTab, submittedOffers]);

  const notify = (message) => { setToast(message); window.setTimeout(() => setToast(""), 2800); };
  const go = (next) => { setPage(next); setSelectedJob(null); setOfferJob(null); setMobileMenu(false); };
  const submitOffer = (event) => {
    event.preventDefault();
    if (!offerPrice || Number(offerPrice) <= 0) { notify("Enter a valid offer amount."); return; }
    setSubmittedOffers(current => [...current.filter(item => item.jobId !== offerJob.id), { jobId: offerJob.id, title: offerJob.title, price: Number(offerPrice), note: offerNote }]);
    setOfferJob(null); setOfferPrice(""); setOfferNote("");
    notify("Demo only: offer preview saved on this device.");
  };
  const requestRecharge = (event) => {
    event.preventDefault();
    if (!Number.isFinite(Number(rechargeAmount)) || Number(rechargeAmount) < 100 || Number(rechargeAmount) > 50000) { notify("Enter an amount between ₹100 and ₹50,000."); return; }
    const utr = rechargeUtr.trim();
    if (utr && !/^[A-Za-z0-9-]{8,22}$/.test(utr)) { notify("Enter a valid 8–22 character UTR/reference, or leave it blank."); return; }
    setWalletRequests(current => [...current, { amount: Number(rechargeAmount), utr, status: "Preview only", id: Date.now() }]);
    setShowRecharge(false); setRechargeUtr("");
    notify("Demo only: recharge request preview saved.");
  };

  return (
    <div className="app-shell">
      <aside className={`sidebar ${mobileMenu ? "sidebar-open" : ""}`}>
        <div className="brand-lockup"><div className="brand-mark"><Activity size={22} strokeWidth={2.5} /></div><div><strong>FindVia</strong><small>PROVIDER APP</small></div><IconButton label="Close menu" className="sidebar-close" onClick={() => setMobileMenu(false)}><X size={20} /></IconButton></div>
        <div className="workspace-label">WORKSPACE</div>
        <nav className="side-nav" aria-label="Main navigation">
          {navItems.map(item => { const Icon = item.icon; return <button key={item.id} className={`nav-link ${page === item.id ? "active" : ""}`} onClick={() => go(item.id)}><Icon size={19} strokeWidth={1.9} /><span>{isHindi ? ({home:"होम",jobs:"काम",work:"मेरे काम",wallet:"वॉलेट",profile:"प्रोफ़ाइल"}[item.id]) : item.label}</span>{item.id === "jobs" && <span className="nav-count">3</span>}</button>; })}
        </nav>
        <div className="sidebar-spacer" />
        <div className="sidebar-help"><div className="help-icon"><CircleHelp size={19} /></div><strong>Need a hand?</strong><p>We're here to help you get work done.</p><button onClick={() => notify("Support will be connected in a later step.")}>Get support <ArrowRight size={14} /></button></div>
        <div className="sidebar-user"><div className="avatar">RS</div><div className="user-copy"><strong>{profileName}</strong><span>Provider account · Demo</span></div><ChevronDown size={16} /></div>
      </aside>

      {mobileMenu && <button className="scrim" aria-label="Close menu overlay" onClick={() => setMobileMenu(false)} />}

      <main className="main-panel">
        <header className="topbar">
          <div className="topbar-left"><IconButton label="Open menu" className="menu-toggle" onClick={() => setMobileMenu(true)}><Menu size={21} /></IconButton><div className="breadcrumb">{isHindi ? "प्रदाता कार्यक्षेत्र" : "Provider workspace"} <span>/</span> <strong>{isHindi ? ({home:"होम",jobs:"काम",work:"मेरे काम",wallet:"वॉलेट",profile:"प्रोफ़ाइल",account:"खाता",verification:"सत्यापन",notifications:"सूचनाएँ",support:"सहायता"}[page] || "विवरण") : (navItems.find(item => item.id === page)?.label || "Details")}</strong></div></div>
          <div className="topbar-actions"><button className="language-toggle" type="button" onClick={() => setLanguage(value => value === "English" ? "Hindi" : "English")} aria-label={isHindi ? "Switch app language to English" : "ऐप की भाषा हिंदी करें"}><span className="language-globe">文</span>{isHindi ? "हिंदी" : "English"} <ChevronDown size={13} /></button><div className="demo-indicator"><span /> {isHindi ? "पूर्वावलोकन" : "Preview mode"}</div><IconButton label="Notifications" onClick={() => setNotificationsOpen(!notificationsOpen)}><Bell size={19} /><i className="notification-dot" /></IconButton><div className="topbar-avatar">RS</div></div>
        </header>

        {notificationsOpen && <div className="notification-popover"><div className="popover-heading"><strong>Notifications</strong><button onClick={() => setNotificationsOpen(false)} aria-label="Close notifications"><X size={16} /></button></div><div className="notification-item"><span className="notification-symbol green"><BriefcaseBusiness size={16} /></span><div><strong>New jobs in your area</strong><p>3 sample job requests are ready to explore.</p><small>Preview · Just now</small></div></div><div className="notification-item"><span className="notification-symbol yellow"><Wallet size={16} /></span><div><strong>Wallet is in preview mode</strong><p>Connect your new account before adding real money.</p><small>Preview · Today</small></div></div></div>}

        <div className="page-content">
          {page === "home" && !selectedJob && <HomePage go={go} onOpenJob={setSelectedJob} onOffer={setOfferJob} submittedOffers={submittedOffers} available={providerAvailable} setAvailable={setProviderAvailable} language={language} />}
          {page === "jobs" && !selectedJob && <section className="page-section"><div className="page-heading"><div><span className="eyebrow">FIND YOUR NEXT JOB</span><h1>{isHindi ? "काम के अनुरोध" : "Job requests"}</h1><p>{isHindi ? "अपने कौशल और सेवा क्षेत्र से मेल खाने वाला काम देखें।" : "Explore work that matches your skills and service area."}</p></div><div className="heading-icon"><BriefcaseBusiness size={23} /></div></div><div className="filter-row"><div className="search-field"><Search size={18} /><input value={query} onChange={event => setQuery(event.target.value)} placeholder={isHindi ? "काम या क्षेत्र खोजें" : "Search jobs or areas"} aria-label={isHindi ? "काम या क्षेत्र खोजें" : "Search jobs or areas"} /><kbd>/</kbd></div><button className={`button button-secondary filter-button ${filterOpen ? "filter-active" : ""}`} aria-expanded={filterOpen} onClick={() => setFilterOpen(open => !open)}><Filter size={16} /> {isHindi ? "फ़िल्टर" : "Filters"}{categoryFilter !== "All categories" && <span className="filter-dot" />}</button></div>{filterOpen && <div className="filter-panel"><label htmlFor="job-category-filter">{isHindi ? "सेवा श्रेणी" : "Service category"}</label><select id="job-category-filter" value={categoryFilter} onChange={event => setCategoryFilter(event.target.value)}><option>All categories</option>{[...new Set(jobsSeed.map(job => job.category))].map(category => <option key={category}>{category}</option>)}</select><button className="text-button" onClick={() => { setCategoryFilter("All categories"); setQuery(""); }}>{isHindi ? "फ़िल्टर हटाएँ" : "Clear filters"}</button></div>}<div className="tabs" role="tablist" aria-label="Job filters">{["Available", "My offers"].map(tab => <button role="tab" aria-selected={jobTab === tab} className={jobTab === tab ? "selected" : ""} key={tab} onClick={() => setJobTab(tab)}>{isHindi ? (tab === "Available" ? "उपलब्ध काम" : "मेरे ऑफ़र") : tab}{tab === "My offers" && submittedOffers.length > 0 && <span className="tab-count">{submittedOffers.length}</span>}</button>)}</div><div className="section-subheading"><strong>{jobTab === "Available" ? (isHindi ? "आपके लिए सुझाव" : "Recommended for you") : (isHindi ? "आपके भेजे ऑफ़र" : "Offers you sent")}</strong><span>{filteredJobs.length} {isHindi ? "काम" : (filteredJobs.length === 1 ? "job" : "jobs")}</span></div>{filteredJobs.length ? <div className="job-list">{filteredJobs.map(job => <JobCard key={job.id} job={job} onOpen={setSelectedJob} onOffer={setOfferJob} language={language} />)}</div> : <div className="empty-state"><Search size={25} /><strong>{isHindi ? "कोई काम नहीं मिला" : "No jobs found"}</strong><p>{isHindi ? "दूसरी खोज करें या उपलब्ध काम देखें।" : "Try a different search or check available jobs."}</p><button className="button button-secondary" onClick={() => { setQuery(""); setCategoryFilter("All categories"); setJobTab("Available"); }}>{isHindi ? "फ़िल्टर हटाएँ" : "Clear filters"}</button></div>}</section>}

          {selectedJob && <JobDetails job={selectedJob} onBack={() => setSelectedJob(null)} onOffer={setOfferJob} />}
          {page === "work" && !selectedJob && <MyWorkPage offers={submittedOffers} go={go} language={language} notify={notify} />}
          {page === "wallet" && !selectedJob && <WalletPage onRecharge={() => setShowRecharge(true)} requests={walletRequests} language={language} />}
          {page === "profile" && !selectedJob && <ProfilePage name={profileName} setName={setProfileName} service={profileService} setService={setProfileService} skills={profileSkills} setSkills={setProfileSkills} areas={serviceAreas} setAreas={setServiceAreas} language={language} setLanguage={setLanguage} notify={notify} go={go} />}
          {page === "account" && <AccountAccessPage go={go} notify={notify} language={language} />}\n          {page === "verification" && <VerificationPage notify={notify} go={go} language={language} />}
          {page === "notifications" && <NotificationsPage go={go} language={language} />}
          {page === "support" && <SupportPage notify={notify} language={language} />}
        </div>

        <footer className="app-footer"><span>© 2026 FindVia</span><span><ShieldCheck size={14} /> Your work. Your growth.</span><span>Preview build · No real transactions</span></footer>
      </main>

      <nav className="mobile-bottom-nav" aria-label="Mobile navigation">{navItems.map(item => { const Icon = item.icon; return <button key={item.id} className={page === item.id ? "active" : ""} onClick={() => go(item.id)}><Icon size={20} /><span>{isHindi ? ({home:"होम",jobs:"काम",work:"मेरे काम",wallet:"वॉलेट",profile:"प्रोफ़ाइल"}[item.id]) : item.label}</span></button>; })}</nav>

      {offerJob && <div className="modal-backdrop" role="presentation" onMouseDown={event => { if (event.target === event.currentTarget) setOfferJob(null); }}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="offer-title"><div className="modal-heading"><div><span className="eyebrow">JOB OFFER</span><h2 id="offer-title">{isHindi ? "अपना ऑफ़र भेजें" : "Send your offer"}</h2><p>{offerJob.title}</p></div><IconButton label="Close dialog" onClick={() => setOfferJob(null)}><X size={20} /></IconButton></div><div className="preview-notice"><Sparkles size={17} /><span>This is a preview. Your offer won't reach a customer until the backend is connected.</span></div><form onSubmit={submitOffer}><label htmlFor="offer-price">{isHindi ? "आपकी कीमत (₹)" : "Your price (₹)"}</label><div className="price-input"><IndianRupee size={19} /><input id="offer-price" type="number" min="1" step="1" required value={offerPrice} onChange={event => setOfferPrice(event.target.value)} placeholder="Enter your offer amount" /></div><label htmlFor="offer-note">{isHindi ? "छोटा संदेश" : "Short message"} <span className="optional">{isHindi ? "वैकल्पिक" : "Optional"}</span></label><textarea id="offer-note" value={offerNote} onChange={event => setOfferNote(event.target.value)} maxLength="240" placeholder="Tell the customer how you can help…" rows="3" /><div className="modal-actions"><button type="button" className="button button-secondary" onClick={() => setOfferJob(null)}>{isHindi ? "रद्द करें" : "Cancel"}</button><button type="submit" className="button button-primary">{isHindi ? "ऑफ़र का पूर्वावलोकन" : "Preview offer"} <ArrowRight size={16} /></button></div></form></section></div>}

      {showRecharge && <div className="modal-backdrop" role="presentation" onMouseDown={event => { if (event.target === event.currentTarget) setShowRecharge(false); }}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="recharge-title"><div className="modal-heading"><div><span className="eyebrow">WALLET</span><h2 id="recharge-title">{isHindi ? "रिचार्ज अनुरोध" : "Request a recharge"}</h2><p>{isHindi ? "रिचार्ज अनुरोध का केवल डेमो देखें।" : "Choose an amount to preview a recharge request."}</p></div><IconButton label="Close dialog" onClick={() => setShowRecharge(false)}><X size={20} /></IconButton></div><div className="preview-notice"><ShieldCheck size={17} /><span>{isHindi ? "डेमो में कोई भुगतान नहीं होगा। UTR देने से भुगतान सत्यापित नहीं होता।" : "No money will be collected in preview mode. Entering a UTR does not verify a payment."}</span></div><form onSubmit={requestRecharge}><label htmlFor="recharge-amount">{isHindi ? "रिचार्ज राशि" : "Recharge amount"}</label><div className="amount-options">{["100", "200", "500", "1000", "2000"].map(amount => <button type="button" key={amount} className={rechargeAmount === amount ? "chosen" : ""} onClick={() => setRechargeAmount(amount)}>₹{Number(amount).toLocaleString("en-IN")}</button>)}</div><div className="price-input"><IndianRupee size={19} /><input id="recharge-amount" type="number" min="100" max="50000" step="1" value={rechargeAmount} onChange={event => setRechargeAmount(event.target.value)} required /></div><label htmlFor="recharge-utr">{isHindi ? "UPI UTR / संदर्भ संख्या (वैकल्पिक डेमो)" : "UPI UTR / reference (optional preview)"}</label><input className="form-control" id="recharge-utr" value={rechargeUtr} onChange={event => setRechargeUtr(event.target.value.slice(0,22))} placeholder={isHindi ? "डेमो UTR दर्ज करें" : "Enter demo UTR"} autoComplete="off" /><div className="modal-actions"><button type="button" className="button button-secondary" onClick={() => setShowRecharge(false)}>{isHindi ? "रद्द करें" : "Cancel"}</button><button type="submit" className="button button-primary">{isHindi ? "डेमो अनुरोध" : "Preview request"} <ArrowRight size={16} /></button></div></form></section></div>}

      {toast && <div className="toast" role="status"><Check size={17} />{toast}</div>}
    </div>
  );
}

function HomePage({ go, onOpenJob, onOffer, submittedOffers, available, setAvailable, language }) {
  const hi = language === "Hindi";
  return <section className="page-section home-page"><div className="welcome-row"><div><span className="eyebrow">WEDNESDAY, OCTOBER 21</span><h1>{hi ? "नमस्ते, राहुल" : "Good afternoon, Rahul"} <span className="wave">✳</span></h1><p>{hi ? "आज काम के अच्छे अवसर खोजें।" : "Ready to make today a good workday?"}</p></div><button className={`availability-toggle ${available ? "is-available" : "is-unavailable"}`} onClick={() => setAvailable(value => !value)} aria-pressed={available}><span className="availability-dot" /><span><strong>{available ? (hi ? "काम के लिए उपलब्ध" : "Available for work") : (hi ? "अभी उपलब्ध नहीं" : "Not available")}</strong><small>{available ? (hi ? "आपको काम के अनुरोध मिल सकते हैं" : "You can receive job requests") : (hi ? "नया काम रुका हुआ है" : "New work is paused")}</small></span><span className="availability-switch"><i /></span></button></div>
    <div className="hero-card"><div className="hero-copy"><span className="hero-kicker"><Sparkles size={14} /> {hi ? "आपका प्रोवाइडर स्पेस" : "YOUR PROVIDER SPACE"}</span><h2>{hi ? <>अच्छे काम के लिए<br />बेहतरीन अवसर।</> : <>Good work deserves<br />great opportunities.</>}</h2><p>{hi ? "अपने कौशल के अनुसार काम खोजें, भरोसे के साथ ऑफ़र भेजें और अपने काम को व्यवस्थित रखें।" : "Find jobs that fit your skills, send offers with confidence, and keep your work organised."}</p><button className="button hero-button" onClick={() => go("jobs")}>{hi ? "काम खोजें" : "Explore jobs"} <ArrowRight size={16} /></button></div><div className="hero-art" aria-hidden="true"><div className="art-orbit orbit-one" /><div className="art-orbit orbit-two" /><div className="art-circle"><BriefcaseBusiness size={43} strokeWidth={1.35} /></div><div className="art-chip chip-one"><Zap size={15} />{hi ? "नया काम" : "New work"}</div><div className="art-chip chip-two"><Check size={15} />{hi ? "आपका अगला कदम" : "Your next step"}</div></div></div>
    <div className="metric-grid"><Metric icon={BriefcaseBusiness} label={hi ? "नए अवसर" : "New opportunities"} value={available ? "03" : "—"} note={available ? (hi ? "आपके सेवा क्षेत्र में" : "In your service area") : (hi ? "उपलब्धता रुकी हुई है" : "Availability is paused")} tone="mint" /><Metric icon={MessageCircle} label={hi ? "भेजे गए ऑफ़र" : "Offers sent"} value={String(submittedOffers.length).padStart(2, "0")} note={hi ? "इस डिवाइस का पूर्वावलोकन" : "Preview on this device"} tone="violet" /><Metric icon={Wallet} label={hi ? "वॉलेट बैलेंस" : "Wallet balance"} value="₹0" note={hi ? "खाता जोड़ने पर सक्रिय होगा" : "Connect account to activate"} tone="amber" /></div>
    <div className="content-grid"><div className="content-column"><div className="section-heading"><div><h2>{hi ? "आपके लिए चुने गए काम" : "Jobs picked for you"}</h2><p>{hi ? "आपकी सेवा और क्षेत्र के आधार पर।" : "Based on your service category and area."}</p></div><button className="text-button" onClick={() => go("jobs")}>{hi ? "सभी देखें" : "View all"} <ArrowRight size={15} /></button></div><div className="job-list compact">{jobsSeed.slice(0, 2).map(job => <JobCard key={job.id} job={job} onOpen={onOpenJob} onOffer={onOffer} language={language} />)}</div></div><aside className="side-column"><div className="tip-card"><div className="tip-icon"><Sparkles size={19} /></div><span className="eyebrow">A SMALL TIP</span><h3>Make your profile stand out</h3><p>Add your skills and experience so the right jobs can find you.</p><button className="text-button" onClick={() => go("profile")}>Update profile <ArrowRight size={15} /></button></div><div className="status-card"><div className="status-card-heading"><span className="status-icon"><ShieldCheck size={18} /></span><strong>Provider checklist</strong></div><div className="checklist-row"><span className="check-circle"><Check size={12} /></span><span>Account preview created</span><StatusPill>Demo</StatusPill></div><div className="checklist-row"><span className="check-circle pending"><Clock3 size={12} /></span><span>Identity verification</span><StatusPill tone="warning">Pending setup</StatusPill></div><div className="checklist-row"><span className="check-circle pending"><Clock3 size={12} /></span><span>Connect secure wallet</span><StatusPill tone="warning">Pending setup</StatusPill></div></div></aside></div>
  </section>;
}

function Metric({ icon: Icon, label, value, note, tone }) {
  return <div className="metric-card"><div className={`metric-icon ${tone}`}><Icon size={19} /></div><span className="metric-label">{label}</span><strong className="metric-value">{value}</strong><span className="metric-note">{note}</span></div>;
}

function JobDetails({ job, onBack, onOffer }) {
  const Icon = job.icon;
  return <section className="page-section"><button className="back-link" onClick={onBack}>← Back to jobs</button><div className="page-heading"><div><span className="eyebrow">JOB DETAILS · {job.id}</span><h1>{job.title}</h1><p>Review the request before deciding whether to send an offer.</p></div><div className={`category-icon large ${job.tint}`}><Icon size={26} /></div></div><div className="details-layout"><div className="panel details-panel"><h2>About this job</h2><p className="details-description">{job.detail}</p><div className="detail-line"><MapPin size={18} /><div><strong>Service area</strong><span>{job.area}</span><small>Exact address and customer contact stay private until you're selected.</small></div></div><div className="detail-line"><CalendarDays size={18} /><div><strong>Preferred time</strong><span>{job.date}</span></div></div><div className="detail-line"><BriefcaseBusiness size={18} /><div><strong>Service category</strong><span>{job.category}</span></div></div><div className="privacy-note"><ShieldCheck size={18} /><span>Customer contact details are protected until a provider is selected.</span></div></div><aside className="panel offer-summary"><span className="eyebrow">YOUR OFFER</span><strong className="large-price">Your price</strong><p>Choose a fair price for the work. The customer will review your offer before selecting a provider.</p><div className="summary-divider" /><div className="summary-detail"><span>Job reference</span><strong>{job.id}</strong></div><div className="summary-detail"><span>Offer process</span><strong>One simple step</strong></div><button className="button button-primary full-button" onClick={() => onOffer(job)}>Send an offer <ArrowRight size={16} /></button><p className="fine-print">Preview only. Offers won't be sent until your account is connected.</p></aside></div></section>;
}

function MyWorkPage({ offers, go, language, notify }) {
  const hi = language === "Hindi";
  const [completionOtp, setCompletionOtp] = useState("");
  const [otpPreviewSubmitted, setOtpPreviewSubmitted] = useState(false);
  const [tab, setTab] = useState("Offers");
  const tabs = [
    { label: "Offers", count: offers.length },
    { label: "Matched", count: 1 },
    { label: "Active", count: 1 },
    { label: "Completed", count: 1 }
  ];
  return <section className="page-section">
    <div className="page-heading"><div><span className="eyebrow">{hi ? "आपका काम, एक जगह" : "YOUR WORK, IN ONE PLACE"}</span><h1>{hi ? "मेरे काम" : "My work"}</h1><p>{hi ? "अपने ऑफ़र और काम की अगली स्थिति देखें।" : "Track the jobs you offer on and what happens next."}</p></div><div className="heading-icon"><ClipboardList size={24} /></div></div>
    <div className="preview-notice work-notice"><ShieldCheck size={17} /><span>{hi ? "पूर्वावलोकन: ये रिकॉर्ड इसी डिवाइस पर रहते हैं। ग्राहक चयन और जॉब स्टेटस के लिए सुरक्षित backend चाहिए।" : "Preview mode: these records stay on this device. Customer selection and job status need the secure backend."}</span></div>
    <div className="tabs work-tabs" role="tablist" aria-label="My work status">{tabs.map(item => <button key={item.label} role="tab" aria-selected={tab === item.label} className={tab === item.label ? "selected" : ""} onClick={() => setTab(item.label)}>{hi ? ({Offers:"ऑफ़र",Matched:"चुना गया",Active:"जारी काम",Completed:"पूरा हुआ"}[item.label]) : item.label}<span className="tab-count">{item.count}</span></button>)}</div>
    {tab === "Matched" ? <div className="panel active-job-preview"><div className="active-job-head"><div className="category-icon mint"><Wrench size={21} /></div><div><span className="eyebrow">{hi ? "नमूना मैच" : "SAMPLE MATCH"}</span><h2>{hi ? "रसोई के नल की मरम्मत" : "Kitchen sink tap repair"}</h2><p>{hi ? "वैशाली नगर, जयपुर · डेमो ग्राहक जानकारी" : "Vaishali Nagar, Jaipur · Demo customer information"}</p></div><StatusPill tone="warning">{hi ? "डेमो" : "Demo"}</StatusPill></div><div className="preview-notice"><ShieldCheck size={17}/><span>{hi ? "मैच के बाद ही संपर्क उपलब्ध होता है। वास्तविक ग्राहक विवरण इस डेमो में नहीं दिखाए जाते।" : "Contact is available only after a match. Real customer details are not shown in this demo."}</span></div><div className="job-timeline"><div className="timeline-step done"><span><Check size={13}/></span><div><strong>{hi ? "ग्राहक ने ऑफ़र चुना" : "Customer selected an offer"}</strong><small>{hi ? "डेमो स्थिति; कोई वास्तविक ग्राहक नहीं जुड़ा है" : "Demo state; no real customer is connected"}</small></div></div><div className="timeline-step"><span>2</span><div><strong>{hi ? "काम शुरू करें" : "Start the job"}</strong><small>{hi ? "असली ऐप में मैच के बाद सुरक्षित संपर्क खुलेगा" : "Secure contact will unlock after matching in the real app"}</small></div></div></div><button className="button button-primary" onClick={() => notify(hi ? "यह डेमो है। असली जॉब स्टेटस backend से बदलेगा।" : "Demo only. Real job status changes through the backend.")}>{hi ? "काम शुरू करने का पूर्वावलोकन" : "Preview start-work step"} <ArrowRight size={16}/></button></div> : tab === "Active" ? <div className="panel active-job-preview"><div className="active-job-head"><div className="category-icon mint"><Wrench size={21} /></div><div><span className="eyebrow">{hi ? "डेमो मिलान" : "SAMPLE MATCH"}</span><h2>{hi ? "रसोई के नल की मरम्मत" : "Kitchen sink tap repair"}</h2><p>{hi ? "वैशाली नगर, जयपुर · ग्राहक की जानकारी अभी डेमो है" : "Vaishali Nagar, Jaipur · Sample customer details only"}</p></div><StatusPill tone="warning">{hi ? "पूर्वावलोकन" : "Preview"}</StatusPill></div><div className="job-timeline"><div className="timeline-step done"><span><Check size={13}/></span><div><strong>{hi ? "ऑफ़र चुना गया" : "Offer selected"}</strong><small>{hi ? "सुरक्षित संपर्क मैच के बाद ही खुलेगा" : "Secure contact opens only after matching"}</small></div></div><div className="timeline-step done"><span><Check size={13}/></span><div><strong>{hi ? "काम जारी है" : "Work in progress"}</strong><small>{hi ? "काम पूरा होने पर ग्राहक से OTP लें" : "Ask the customer for the OTP after the job is done"}</small></div></div><div className="timeline-step"><span>3</span><div><strong>{hi ? "ग्राहक OTP से पुष्टि करेगा" : "Customer confirms with OTP"}</strong><small>{hi ? "सर्वर सत्यापन के बाद ही काम पूरा और कमीशन दर्ज होगा" : "Completion and commission are recorded only after server verification"}</small></div></div></div><form className="completion-otp-form" onSubmit={event => {event.preventDefault(); setOtpPreviewSubmitted(true);}}><label htmlFor="completion-otp">{hi ? "ग्राहक का completion OTP (केवल UI डेमो)" : "Customer completion OTP (UI preview only)"}</label><input id="completion-otp" className="form-control otp-input" inputMode="numeric" autoComplete="off" maxLength="6" value={completionOtp} onChange={event => {setCompletionOtp(event.target.value.replace(/\D/g,"").slice(0,6));setOtpPreviewSubmitted(false);}} placeholder="••••••" /><button className="button button-primary" type="submit" disabled={completionOtp.length !== 6}>{hi ? "OTP प्रक्रिया का पूर्वावलोकन" : "Preview OTP flow"} <ShieldCheck size={16}/></button>{otpPreviewSubmitted && <p className="otp-preview-feedback" role="status">{hi ? "यह केवल डेमो है। OTP सत्यापित नहीं हुआ और कोई काम पूरा/वॉलेट अपडेट नहीं किया गया।" : "Preview only: the OTP was not verified and no job or wallet was updated."}</p>}</form><div className="security-footnote"><ShieldCheck size={17}/><p>{hi ? "यह स्क्रीन केवल UI डेमो है। असली OTP सत्यापन सर्वर पर होगा।" : "UI demo only. Real OTP verification must happen securely on the server."}</p></div></div> : tab === "Completed" ? <div className="panel active-job-preview"><div className="active-job-head"><div className="category-icon mint"><CheckCircle2 size={21}/></div><div><span className="eyebrow">{hi ? "नमूना रिकॉर्ड" : "SAMPLE RECORD"}</span><h2>{hi ? "सीलिंग फैन इंस्टॉलेशन" : "Ceiling fan installation"}</h2><p>{hi ? "मानसरोवर, जयपुर · डेमो जॉब" : "Mansarovar, Jaipur · Demo job"}</p></div><StatusPill tone="success">{hi ? "डेमो पूरा" : "Demo complete"}</StatusPill></div><div className="job-timeline"><div className="timeline-step done"><span><Check size={13}/></span><div><strong>{hi ? "काम पूरा हुआ" : "Work marked complete"}</strong><small>{hi ? "यह केवल नमूना स्थिति है" : "This is a sample status only"}</small></div></div><div className="timeline-step done"><span><ShieldCheck size={13}/></span><div><strong>{hi ? "ग्राहक OTP सत्यापन" : "Customer OTP verification"}</strong><small>{hi ? "असली ऐप में सर्वर सत्यापन आवश्यक होगा" : "Server verification is required in the real app"}</small></div></div><div className="timeline-step done"><span><Wallet size={13}/></span><div><strong>{hi ? "कमीशन लेजर" : "Commission ledger"}</strong><small>{hi ? "वास्तविक राशि अभी गणना नहीं हुई" : "No real amount has been calculated"}</small></div></div></div><div className="preview-notice"><ShieldCheck size={17}/><span>{hi ? "यह उदाहरण है, वास्तविक कमाई या भुगतान रिकॉर्ड नहीं।" : "Example only, not a real earnings or payment record."}</span></div></div> : tab === "Offers" && offers.length > 0 ? <div className="job-list">{offers.slice().reverse().map(offer => <article className="job-card work-offer-card" key={offer.jobId}><div className="job-card-top"><div className="category-icon mint"><BriefcaseBusiness size={21} /></div><div className="job-main"><div className="job-title-row"><h3>{offer.title}</h3><span className="job-id">{offer.jobId}</span></div><p className="job-category">Offer sent · Preview only</p></div><StatusPill tone="warning">Awaiting selection</StatusPill></div><div className="work-offer-bottom"><div><span className="eyebrow">YOUR OFFER</span><strong className="work-offer-price">₹{Number(offer.price).toLocaleString("en-IN")}</strong></div><div className="work-offer-message">{offer.note ? offer.note : "No message added"}</div></div></article>)}</div> : <div className="empty-state work-empty"><div className="empty-icon">{tab === "Completed" ? <CheckCircle2 size={23} /> : <ClipboardList size={23} />}</div><strong>{tab === "Offers" ? "No offers sent yet" : tab === "Matched" ? "No matched jobs yet" : tab === "Active" ? "No active jobs yet" : "No completed jobs yet"}</strong><p>{tab === "Offers" ? (hi ? "उपलब्ध काम देखें और एक ही चरण में अपनी कीमत भेजें।" : "Browse available jobs and send your price in one simple step.") : tab === "Matched" ? (hi ? "ग्राहक द्वारा ऑफ़र चुनने पर काम यहाँ दिखेगा।" : "When a customer selects your offer, the job will appear here.") : tab === "Active" ? (hi ? "काम शुरू होने पर चुना गया काम यहाँ आएगा।" : "Matched work will move here when the job starts.") : (hi ? "ग्राहक OTP सत्यापित करने के बाद पूरा काम यहाँ दिखेगा।" : "After the customer verifies the completion OTP, finished work will appear here.")}</p>{tab === "Offers" && <button className="button button-primary" onClick={() => go("jobs")}>{hi ? "काम खोजें" : "Explore jobs"} <ArrowRight size={16} /></button>}</div>}
    <div className="work-flow-hint"><div className="work-flow-step"><span>1</span><div><strong>{hi ? "एक ऑफ़र भेजें" : "Send one offer"}</strong><p>{hi ? "अपनी कीमत चुनकर ग्राहक को भेजें।" : "Choose your price and send it to the customer."}</p></div></div><div className="work-flow-step"><span>2</span><div><strong>{hi ? "चुने जाएँ" : "Get selected"}</strong><p>{hi ? "चयन के बाद सुरक्षित संपर्क उपलब्ध होगा।" : "After selection, secure job contact becomes available."}</p></div></div><div className="work-flow-step"><span>3</span><div><strong>{hi ? "OTP से काम पूरा करें" : "Finish with OTP"}</strong><p>{hi ? "काम पूरा होने और कमीशन की पुष्टि सर्वर करेगा।" : "Completion and wallet commission are verified by the server."}</p></div></div></div>
  </section>;
}

function WalletPage({ onRecharge, requests, language }) {
  const hi = language === "Hindi";
  return <section className="page-section"><div className="page-heading"><div><span className="eyebrow">YOUR MONEY, CLEARLY TRACKED</span><h1>{hi ? "वॉलेट और कमाई" : "Wallet & earnings"}</h1><p>{hi ? "वॉलेट गतिविधि और हर लेन-देन का विवरण देखें।" : "See your wallet activity and understand each transaction."}</p></div><div className="heading-icon"><Wallet size={24} /></div></div><div className="wallet-hero"><div className="wallet-topline"><span><Wallet size={16} /> PROVIDER WALLET</span><StatusPill tone="warning">Preview mode</StatusPill></div><span className="wallet-label">{hi ? "उपलब्ध वॉलेट बैलेंस" : "Available wallet balance"}</span><strong className="wallet-balance">₹0.00</strong><p>{hi ? "सुरक्षित खाता जुड़ने के बाद वास्तविक बैलेंस दिखेगा।" : "Real balance will appear after secure account connection."}</p><button className="button wallet-button" onClick={onRecharge}><ArrowDownLeft size={16} /> {hi ? "रिचार्ज अनुरोध" : "Request recharge"}</button><div className="wallet-decoration"><div /><div /><div /></div></div><div className="wallet-stats"><div className="wallet-stat"><span><ArrowUpRight size={16} /> {hi ? "दिया गया कमीशन" : "Commission paid"}</span><strong>₹0.00</strong><small>Preview only</small></div><div className="wallet-stat"><span><IndianRupee size={16} /> {hi ? "सेवा से कमाई" : "Service earnings"}</span><strong>₹0.00</strong><small>Jobs completed</small></div><div className="wallet-stat"><span><CreditCard size={16} /> {hi ? "रिचार्ज अनुरोध" : "Recharge requests"}</span><strong>{requests.length.toString().padStart(2, "0")}</strong><small>Saved on this device</small></div></div><div className="panel transaction-panel"><div className="section-heading"><div><h2>{hi ? "हाल की गतिविधि" : "Recent activity"}</h2><p>{hi ? "आपके वॉलेट का लेजर यहाँ दिखेगा।" : "Your wallet ledger will appear here."}</p></div><FileText size={21} className="muted-icon" /></div>{requests.length ? requests.slice().reverse().map(item => <div className="transaction-row" key={item.id}><div className="transaction-icon"><ArrowDownLeft size={17} /></div><div className="transaction-copy"><strong>{hi ? "रिचार्ज अनुरोध (डेमो)" : "Recharge request preview"}</strong><span>{item.utr ? `UTR: ${item.utr}` : (hi ? "UTR नहीं जोड़ा" : "No UTR added")} · {hi ? "प्रबंधन को नहीं भेजा गया" : "Not sent to management"}</span></div><strong className="transaction-amount">₹{item.amount.toLocaleString("en-IN")}</strong><StatusPill tone="warning">{hi ? "डेमो" : "Preview"}</StatusPill></div>) : <div className="empty-state compact-empty"><div className="empty-icon"><Activity size={22} /></div><strong>No transactions yet</strong><p>When your account is connected, wallet activity will show up here.</p></div>}</div><div className="security-footnote"><ShieldCheck size={17} /><p><strong>Security first.</strong> Wallet balances and commission records will be calculated on the server. This preview cannot accept or move real money.</p></div></section>;
}

function ProfilePage({ name, setName, service, setService, skills, setSkills, areas, setAreas, language, setLanguage, notify, go }) {
  const hi = language === "Hindi";
  const [photo, setPhoto] = useState("");
  useEffect(() => () => { if (photo.startsWith("blob:")) URL.revokeObjectURL(photo); }, [photo]);
  return <section className="page-section"><div className="page-heading"><div><span className="eyebrow">{hi ? "आपकी पेशेवर पहचान" : "YOUR PROFESSIONAL IDENTITY"}</span><h1>{hi ? "मेरी प्रोफ़ाइल" : "My profile"}</h1><p>{hi ? "सही अवसरों के लिए अपने कौशल और विवरण तैयार रखें।" : "Keep your skills and details ready for the right opportunities."}</p></div><div className="heading-icon"><Settings2 size={24} /></div></div><div className="profile-layout"><div className="panel profile-card"><div className="profile-cover" /><div className="profile-avatar">{photo ? <img src={photo} alt={hi ? "प्रोफ़ाइल फ़ोटो पूर्वावलोकन" : "Profile photo preview"} /> : (name.trim().split(/\s+/).slice(0,2).map(part => part[0] || "").join("").toUpperCase() || "FV")}</div><label className="photo-picker" htmlFor="provider-photo">{hi ? "फ़ोटो चुनें" : "Choose photo"} <input id="provider-photo" type="file" accept="image/*" onChange={event => { const file = event.target.files?.[0]; if (file) setPhoto(URL.createObjectURL(file)); }} /></label><div className="profile-intro"><h2>{name || (hi ? "आपका नाम" : "Your name")}</h2><p><MapPin size={14} /> Jaipur, Rajasthan · {hi ? "डेमो प्रोफ़ाइल" : "Demo profile"}</p><StatusPill tone="warning">{hi ? "सत्यापन जुड़ा नहीं" : "Verification not connected"}</StatusPill></div><div className="profile-progress"><div><span>{hi ? "प्रोफ़ाइल पूर्णता" : "Profile completeness"}</span><strong>{hi ? "पूर्वावलोकन" : "Preview"}</strong></div><div className="progress-track"><span style={{ width: "45%" }} /></div><small>{hi ? "सेटअप के बाद सत्यापन और खाता विवरण सक्रिय होंगे।" : "Verification and account details will be enabled after setup."}</small></div></div><div className="panel profile-form"><div className="section-heading"><div><h2>{hi ? "मूल जानकारी" : "Basic information"}</h2><p>{hi ? "ये जानकारी अभी केवल इस पूर्वावलोकन में बदलती है।" : "These fields currently update only this preview."}</p></div></div><label htmlFor="provider-name">{hi ? "पूरा नाम" : "Full name"}</label><input className="form-control" id="provider-name" value={name} onChange={event => setName(event.target.value)} maxLength="70" /><label htmlFor="provider-service">{hi ? "मुख्य सेवा" : "Main service"}</label><select className="form-control" id="provider-service" value={service} onChange={event => setService(event.target.value)}><option>Plumbing</option><option>Electrical</option><option>AC repair</option><option>Carpentry</option><option>Painting</option><option>Masonry</option><option>Appliance repair</option><option>Other</option></select><label htmlFor="provider-language">{hi ? "ऐप की भाषा" : "App language"}</label><select className="form-control" id="provider-language" value={language} onChange={event => setLanguage(event.target.value)}><option>English</option><option>Hindi</option></select><label>{hi ? "आपके कौशल" : "Your skills"}</label><div className="choice-chip-grid">{["Plumbing","Electrical","AC repair","Carpentry","Painting","Appliance repair"].map(skill => <label className={`choice-chip ${skills.includes(skill) ? "choice-chip-selected" : ""}`} key={skill}><input type="checkbox" checked={skills.includes(skill)} onChange={event => setSkills(current => event.target.checked ? [...current, skill] : current.filter(item => item !== skill))}/><span>{skill}</span></label>)}</div><label>{hi ? "सेवा क्षेत्र" : "Service areas"}</label><div className="choice-chip-grid">{["Vaishali Nagar","Mansarovar","Jagatpura","Malviya Nagar","C-Scheme"].map(area => <label className={`choice-chip ${areas.includes(area) ? "choice-chip-selected" : ""}`} key={area}><input type="checkbox" checked={areas.includes(area)} onChange={event => setAreas(current => event.target.checked ? [...current, area] : current.filter(item => item !== area))}/><span>{area}</span></label>)}</div><button className="button button-primary profile-save" onClick={() => notify(hi ? "जानकारी इस डिवाइस पर सहेजी गई।" : "Preview saved on this device.")}>{hi ? "जानकारी सहेजें" : "Save profile"} <Check size={16} /></button><p className="language-help"><span>文</span> {language === "Hindi" ? "भाषा बदलने के लिए ऊपर हेडर में हिंदी / English बटन दबाएँ।" : "Use the Hindi / English button in the top header to change app language."}</p><div className="profile-info-note"><ShieldCheck size={17} /><span>{hi ? "Supabase जुड़ने के बाद निजी जानकारी और दस्तावेज़ सुरक्षित रूप से रखे जाएंगे।" : "Personal details and documents will be stored securely after Supabase is configured."}</span></div></div></div><div className="panel profile-settings"><button className="settings-row settings-button" onClick={() => go("verification")}><span className="settings-icon"><FileText size={18} /></span><div><strong>{hi ? "सत्यापन दस्तावेज़" : "Verification documents"}</strong><p>{hi ? "पहचान और कौशल के दस्तावेज़" : "Identity and skill documents"}</p></div><StatusPill tone="warning">{hi ? "जुड़ा नहीं" : "Not connected"}</StatusPill><ArrowRight size={17} /></button><button className="settings-row settings-button" onClick={() => go("notifications")}><span className="settings-icon"><Bell size={18} /></span><div><strong>{hi ? "सूचनाएँ" : "Notifications"}</strong><p>{hi ? "काम और वॉलेट अपडेट" : "Job updates and wallet activity"}</p></div><ArrowRight size={17} /></button><button className="settings-row settings-button" onClick={() => go("account")}><span className="settings-icon"><ShieldCheck size={18} /></span><div><strong>{hi ? "खाते में प्रवेश" : "Account access"}</strong><p>{hi ? "साइन इन और खाता सेटअप पूर्वावलोकन" : "Sign in and account setup preview"}</p></div><ArrowRight size={17} /></button><button className="settings-row settings-button" onClick={() => go("support")}><span className="settings-icon"><CircleHelp size={18} /></span><div><strong>{hi ? "मदद और सहायता" : "Help & support"}</strong><p>{hi ? "प्रदाता खाते के लिए सहायता पाएँ" : "Get help with your provider account"}</p></div><ArrowRight size={17} /></button></div></section>;
}



function AccountAccessPage({ go, notify, language }) {
  const hi = language === "Hindi";
  const [mode, setMode] = useState("signin");
  const [phone, setPhone] = useState("");
  const [step, setStep] = useState("details");
  const [otp, setOtp] = useState("");
  const [name, setName] = useState("");
  const validPhone = /^[6-9][0-9]{9}$/.test(phone);
  const submitDetails = event => {
    event.preventDefault();
    if (!validPhone) { notify("Enter a valid 10-digit Indian mobile number."); return; }
    if (mode === "signup" && !name.trim()) { notify("Enter your full name to continue."); return; }
    setStep("otp");
  };
  const verifyPreview = event => {
    event.preventDefault();
    notify("Preview only: real SMS OTP verification is not connected.");
  };
  return <section className="page-section account-page"><button className="back-link" onClick={() => go("profile")}>← {hi ? "प्रोफ़ाइल पर वापस" : "Back to profile"}</button><div className="account-layout"><div className="account-brand"><div className="account-brand-icon"><Activity size={30} /></div><span className="eyebrow">FINDVIA PROVIDER</span><h1>{hi ? "आपका काम, अब आसान।" : "Your work, made simpler."}</h1><p>{hi ? "ऑफ़र, चुने गए काम और कमाई को एक सुरक्षित जगह पर संभालें।" : "Sign in to manage offers, matched jobs and earnings in one secure place."}</p><div className="account-benefit"><ShieldCheck size={18} /><span>{hi ? "ग्राहक द्वारा चुने जाने तक संपर्क विवरण निजी रहते हैं।" : "Contact details stay private until a customer selects you."}</span></div><div className="account-benefit"><Wallet size={18} /><span>{hi ? "वॉलेट और कमीशन अपडेट सुरक्षित रूप से सत्यापित होते हैं।" : "Wallet and commission updates are verified securely."}</span></div></div><div className="panel account-form-panel"><div className="account-mode"><button className={mode === "signin" ? "active" : ""} onClick={() => {setMode("signin");setStep("details");}}>{hi ? "साइन इन" : "Sign in"}</button><button className={mode === "signup" ? "active" : ""} onClick={() => {setMode("signup");setStep("details");}}>{hi ? "खाता बनाएँ" : "Create account"}</button></div><span className="eyebrow">{step === "details" ? (hi ? "स्वागत है" : "WELCOME BACK") : (hi ? "मोबाइल सत्यापन" : "PHONE VERIFICATION")}</span><h2>{step === "details" ? (mode === "signin" ? "Sign in to FindVia" : "Create your provider account") : "Enter verification code"}</h2><p>{step === "details" ? "Use your mobile number to continue." : `A real OTP will be sent to +91 ${phone} after authentication is connected.`}</p>{step === "details" ? <form onSubmit={submitDetails}>{mode === "signup" && <><label htmlFor="account-name">{hi ? "पूरा नाम" : "Full name"}</label><input className="form-control" id="account-name" value={name} onChange={e=>setName(e.target.value)} placeholder={hi ? "अपना नाम लिखें" : "Enter your name"} maxLength="70" required /></>}<label htmlFor="account-phone">{hi ? "मोबाइल नंबर" : "Mobile number"}</label><div className="phone-field"><span>+91</span><input id="account-phone" inputMode="numeric" autoComplete="tel-national" value={phone} onChange={e=>setPhone(e.target.value.replace(/\D/g,"").slice(0,10))} placeholder={hi ? "10 अंकों का मोबाइल नंबर" : "10-digit mobile number"} required /></div><button className="button button-primary full-button" type="submit">{hi ? "आगे बढ़ें" : "Continue"} <ArrowRight size={16} /></button><div className="preview-notice account-notice"><ShieldCheck size={16} /><span>{hi ? "केवल डेमो। SMS नहीं भेजा जाता और खाता नहीं बनता।" : "Preview only. No SMS is sent and no account is created."}</span></div></form> : <form onSubmit={verifyPreview}><label htmlFor="account-otp">{hi ? "6 अंकों का OTP" : "6-digit OTP"}</label><input className="form-control otp-input" id="account-otp" inputMode="numeric" autoComplete="one-time-code" value={otp} onChange={e=>setOtp(e.target.value.replace(/\D/g,"").slice(0,6))} placeholder={hi ? "OTP दर्ज करें" : "Enter OTP"} maxLength="6" required /><button className="button button-primary full-button" type="submit">{hi ? "नंबर सत्यापित करें" : "Verify number"} <ShieldCheck size={16} /></button><button type="button" className="text-button account-back" onClick={()=>setStep("details")}>{hi ? "मोबाइल नंबर बदलें" : "Change mobile number"}</button></form>}<button className="text-button account-preview-link" onClick={()=>go("home")}>{hi ? "डेमो वर्कस्पेस खोलें" : "Continue to preview workspace"} <ArrowRight size={15} /></button></div></div></section>;
}

function VerificationPage({ notify, go, language }) {
  const hi = language === "Hindi";
  const [documentType, setDocumentType] = useState("Identity proof");
  const [fileName, setFileName] = useState("");
  return <section className="page-section">
    <button className="back-link" onClick={() => go("profile")}>← Back to profile</button>
    <div className="page-heading"><div><span className="eyebrow">ACCOUNT SAFETY</span><h1>{hi ? "प्रदाता सत्यापन" : "Provider verification"}</h1><p>{hi ? "सत्यापन से ग्राहकों को प्रदाता चुनने में भरोसा मिलता है।" : "Verification helps customers feel confident choosing a provider."}</p></div><div className="heading-icon"><ShieldCheck size={24} /></div></div>
    <div className="preview-notice"><ShieldCheck size={17} /><span>{hi ? "दस्तावेज़ अपलोड और समीक्षा अभी जुड़े नहीं हैं। इस डेमो में असली पहचान दस्तावेज़ न दें।" : "Document upload and review are not connected yet. Do not submit real identity documents in this preview."}</span></div>
    <div className="panel verification-panel"><h2>{hi ? "दस्तावेज़ सूची" : "Documents checklist"}</h2><div className="verification-row"><span className="verification-icon"><FileText size={19} /></span><div><strong>{hi ? "पहचान प्रमाण" : "Identity proof"}</strong><p>{hi ? "खाता सत्यापन के लिए सरकारी पहचान पत्र आवश्यक है।" : "Government ID required for account verification."}</p></div><StatusPill tone="warning">Not submitted</StatusPill></div><div className="verification-row"><span className="verification-icon"><BriefcaseBusiness size={19} /></span><div><strong>{hi ? "कौशल या अनुभव प्रमाण" : "Skill or experience proof"}</strong><p>{hi ? "प्रमाणपत्र या काम का प्रमाण वैकल्पिक है।" : "Optional certificates or relevant work proof."}</p></div><StatusPill>Optional</StatusPill></div>
    <label htmlFor="doc-type">{hi ? "दस्तावेज़ का प्रकार" : "Document type"}</label><select className="form-control" id="doc-type" value={documentType} onChange={e => setDocumentType(e.target.value)}><option>Identity proof</option><option>Skill certificate</option><option>Experience proof</option></select><label htmlFor="doc-file">{hi ? "फ़ाइल चुनें (केवल डेमो)" : "Choose a file (preview only)"}</label><input className="form-control file-control" id="doc-file" type="file" accept="image/*,.pdf" onChange={e => setFileName(e.target.files?.[0]?.name || "")} /><p className="file-name">{fileName || "No file selected"}</p><button className="button button-primary" onClick={() => notify(fileName ? (hi ? "डेमो: फ़ाइल चुनी गई, अपलोड नहीं हुई।" : "Preview only: file was selected but not uploaded.") : (hi ? "पहले फ़ाइल चुनें। कोई दस्तावेज़ अपलोड नहीं होता।" : "Choose a file first. No documents are uploaded in preview mode."))}>{hi ? "आगे बढ़ें" : "Continue"} <ArrowRight size={16} /></button></div>
  </section>;
}

function NotificationsPage({ go, language }) {
  const hi = language === "Hindi";
  return <section className="page-section"><div className="page-heading"><div><span className="eyebrow">STAY IN THE LOOP</span><h1>{hi ? "सूचनाएँ" : "Notifications"}</h1><p>{hi ? "काम और वॉलेट के महत्वपूर्ण अपडेट यहाँ दिखेंगे।" : "Important job and wallet updates will appear here."}</p></div><div className="heading-icon"><Bell size={24} /></div></div><div className="preview-notice"><Activity size={17} /><span>{hi ? "ये केवल उदाहरण हैं। backend जुड़ने पर असली सूचनाएँ आएँगी।" : "These are examples only. Live notifications arrive after the backend is connected."}</span></div><div className="panel notification-page-list"><div className="notification-item"><span className="notification-symbol green"><BriefcaseBusiness size={16} /></span><div><strong>New jobs in your service area</strong><p>Sample job requests are ready to explore.</p><small>Preview · Today</small></div><StatusPill>Info</StatusPill></div><div className="notification-item"><span className="notification-symbol yellow"><Wallet size={16} /></span><div><strong>Wallet setup needed</strong><p>Connect your account before using real wallet features.</p><small>Preview · Today</small></div><StatusPill tone="warning">Action needed</StatusPill></div><div className="notification-item"><span className="notification-symbol green"><ShieldCheck size={16} /></span><div><strong>Keep your details private</strong><p>{hi ? "ग्राहक संपर्क केवल चयन के बाद ही खुलना चाहिए।" : "Your customer contact access should unlock only after selection."}</p><small>Security reminder</small></div></div></div><button className="button button-secondary" onClick={() => go("jobs")}>Explore jobs <ArrowRight size={16} /></button></section>;
}

function SupportPage({ notify, language }) {
  const hi = language === "Hindi";
  const [topic, setTopic] = useState("Job or offer");
  const [message, setMessage] = useState("");
  return <section className="page-section"><div className="page-heading"><div><span className="eyebrow">WE'RE HERE TO HELP</span><h1>{hi ? "मदद और सहायता" : "Help & support"}</h1><p>{hi ? "जवाब पाएँ या सहायता अनुरोध तैयार करें।" : "Find answers or prepare a support request."}</p></div><div className="heading-icon"><CircleHelp size={24} /></div></div><div className="content-grid support-grid"><div className="panel support-faq"><h2>{hi ? "आम सवाल" : "Common questions"}</h2><details><summary>When can I see customer contact details?</summary><p>{hi ? "ग्राहक द्वारा आपका ऑफ़र चुनने और काम मैच होने के बाद ही।" : "Only after the customer selects your offer and the job is matched."}</p></details><details><summary>When is commission deducted?</summary><p>{hi ? "ग्राहक का completion OTP सुरक्षित सर्वर द्वारा सत्यापित होने के बाद।" : "After the customer completion OTP is verified by the secure server."}</p></details><details><summary>Can I recharge the wallet in preview mode?</summary><p>{hi ? "नहीं। डेमो अनुरोध से पैसे नहीं चलते और प्रबंधन तक अनुरोध नहीं पहुँचता।" : "No. Preview requests do not move money or reach management."}</p></details></div><div className="panel support-form"><h2>{hi ? "सहायता अनुरोध" : "Support request"}</h2><p>{hi ? "यह स्थानीय पूर्वावलोकन है; संदेश नहीं भेजा जाएगा।" : "This form is a local preview and will not send a message."}</p><label htmlFor="support-topic">{hi ? "किस विषय में सहायता चाहिए?" : "What do you need help with?"}</label><select className="form-control" id="support-topic" value={topic} onChange={e => setTopic(e.target.value)}><option>Job or offer</option><option>Wallet or commission</option><option>Profile verification</option><option>Account access</option><option>Other</option></select><label htmlFor="support-message">{hi ? "समस्या बताएँ" : "Describe the issue"}</label><textarea className="form-control" id="support-message" rows="4" maxLength="600" value={message} onChange={e => setMessage(e.target.value)} placeholder="Tell us what happened…" /><button className="button button-primary" onClick={() => notify(message.trim() ? (hi ? "डेमो: सहायता अनुरोध अभी नहीं भेजा गया।" : "Preview only: support request is not sent yet.") : (hi ? "पहले समस्या बताएँ।" : "Please describe your issue first."))}>{hi ? "अनुरोध तैयार करें" : "Prepare request"} <ArrowRight size={16} /></button></div></div></section>;
}

export default App;